<?php
namespace App\Http\Controllers; use App\Models\{TrainingEvaluation,TrainingEvaluationAttempt}; use App\Services\{TrainingAiGradingService,TrainingEvaluationScoringService,TrainingEvaluationService}; use Illuminate\Http\Request;
class PublicTrainingEvaluationController extends Controller{public function show(TrainingEvaluation$evaluation,string$token,TrainingEvaluationService$s){$access=$s->findAccess($evaluation,$token);$attempt=$evaluation->attempts()->where('attendance_participant_id',$access->attendance_participant_id)->where('status','started')->latest()->first()??$s->start($evaluation,$access);$questions=$evaluation->questions()->with(['options'=>fn($q)=>$q->select('id','evaluation_question_id','option_text','sort_order')])->get();return view('training.evaluations.take',compact('evaluation','token','access','attempt','questions'));}public function submit(TrainingEvaluation$evaluation,string$token,Request$r,TrainingEvaluationService$s,TrainingEvaluationScoringService$scoring,TrainingAiGradingService$aiGrading){$access=$s->findAccess($evaluation,$token);$d=$r->validate(['attempt_id'=>'required|integer','answers'=>'nullable|array','answers.*'=>'array','answers.*.*'=>'integer','text_answers'=>'nullable|array','text_answers.*'=>'nullable|string|max:5000']);$attempt=TrainingEvaluationAttempt::where('training_evaluation_id',$evaluation->id)->where('attendance_participant_id',$access->attendance_participant_id)->whereKey($d['attempt_id'])->firstOrFail();$attempt=$s->submit($attempt,$d['answers']??[],$d['text_answers']??[],$scoring,$aiGrading);return view('training.evaluations.result',compact('evaluation','attempt','token'));}}
